/** `#rgb` or `#rrggbb` -> sRGB channels in 0..1, for WebGL uniforms. Invalid input returns black. */
export function hexToRgb01(hex: string): [number, number, number] {
  let value = hex.trim().replace(/^#/, '');
  if (value.length === 3) value = value.replace(/./g, (c) => c + c);
  if (!/^[0-9a-fA-F]{6}$/.test(value)) return [0, 0, 0];
  const n = Number.parseInt(value, 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

/**
 * A colour at an alpha, resolved for WebGL and canvas. In CSS the same token reads
 * `rgb(var(--c-<role>) / var(--alpha-<step>))`.
 */
export interface ThemeComposite {
  readonly hex: `#${string}`;
  readonly alpha: number;
}

